const A=0.5,C=2,S=1.2,H=0.4,B0=1.3;
const Lf=(w,b)=>0.5*(A*w*w+C*b*b);
const Y=(w,b)=>H*Lf(w,b);
const cl=(v,m)=>Math.max(-m,Math.min(m,v));
function rnd(n){const x=Math.sin(n)*43758.5453;return x-Math.floor(x);}
function nz(seed,run,k){const u=Math.max(rnd(seed*1.37+run*91.3+k*7.77+0.5),1e-9),v=rnd(seed*2.71+run*53.1+k*3.91+1.3),r=Math.sqrt(-2*Math.log(u));return [r*Math.cos(6.2832*v),r*Math.sin(6.2832*v)];}
function stepV(s,inp,seed){const B=+inp.batchSize,f=Math.sqrt((64-B)/(63*B)),n=nz(seed,s.run,s.k),lr=inp.learningRate;return [-lr*(A*s.w+S*f*n[0]),-lr*(C*s.b+S*f*n[1])];}
function fresh(w0,run,old){return {w0,run,old,w:w0,b:B0,k:0,t:0,st:0,path:[]};}
export function initialState(){return fresh(-2.8,0,[]);}
function adv(s,inp,seed){if(s.st)return s;const d=stepV(s,inp,seed),w=s.w+d[0],b=s.b+d[1],k=s.k+1,path=s.path.concat([[w,b]]).slice(-40),st=(Math.abs(w)>4||Math.abs(b)>2)?2:k>=40?1:0;return {...s,w,b,k,path,st};}
export function reduce({state:s,event:e,inputs,seed}){
if(e.type==='step'){if(s.st)return s;const t=s.t+1;return t%8?{...s,t}:adv({...s,t},inputs,seed);}
if(e.type==='action'){if(e.action==='oneStep')return adv(s,inputs,seed);if(e.action==='keepPath')return fresh(s.w0,s.run+1,s.path);}
if(e.type==='parameter'&&e.parameter!=='showTrueGradient')return fresh(s.w0,s.run,s.old);
if((e.type==='drag_move'||e.type==='drag_end')&&e.node==='start')return fresh(cl(e.value,3.2),s.run,s.old);
return s;}
function pt(p){if(!p)return {visible:false};const w=cl(p[0],4),b=cl(p[1],2);return {visible:true,position:[w,Y(w,b)+0.03,b]};}
function arr(x,y,z,d,on){const m=Math.hypot(d[0],d[1]);if(!on||m<1e-6)return {visible:false};const q=0.7071;return {visible:true,position:[x,y,z],scale:[1,Math.max(m,0.3),1],quaternion:[d[1]/m*q,0,-d[0]/m*q,q]};}
export function evaluate({inputs,seed,state:s}){const n={};
for(let i=0;i<40;i++){n['p'+i]=pt(s.path[i]);n['o'+i]=pt(s.old[i]);}
const w=cl(s.w,4),b=cl(s.b,2),y=Y(w,b)+0.18,lr=inputs.learningRate;
n.ball={position:[w,y,b]};
n.start={position:[s.w0,Y(s.w0,B0)+0.04,B0]};
n.stepArrow=arr(w,y,b,stepV(s,inputs,seed),!s.st);
n.trueArrow=arr(w,y+0.06,b,[-lr*A*s.w,-lr*C*s.b],inputs.showTrueGradient&&!s.st);
n.status={text:s.st===2?'Diverged':s.st===1?'Done: 40 steps':s.k?'Running':'Ready'};
return {nodes:n,readouts:{loss:Lf(s.w,s.b),dist:Math.hypot(s.w,s.b),stepNo:s.k}};}

